package com.ashkan.hotel;

import java.math.BigDecimal;
import java.sql.*;
import java.time.LocalDate;
import java.util.*;

/** Booking bounded-context persistence for room inventory and rate plans. */
public final class CommercialRepository extends JdbcDomainRepository {
    public record Room(String id,String roomType,String roomNumber,int floor,int capacity,String status,List<String> amenities) {
        public Room { required(id,"id"); required(roomType,"roomType"); required(roomNumber,"roomNumber"); if(floor<0||capacity<1||capacity>20)throw new IllegalArgumentException("Invalid floor or capacity"); status=Objects.requireNonNullElse(status,"ACTIVE").toUpperCase(Locale.ROOT); if(!Set.of("ACTIVE","OUT_OF_SERVICE","INACTIVE").contains(status))throw new IllegalArgumentException("Invalid room status"); amenities=List.copyOf(Objects.requireNonNullElse(amenities,List.of())); }
    }
    public record RatePlan(String id,String name,String roomType,String currency,BigDecimal baseRate,BigDecimal weekendMultiplier,BigDecimal highDemandMultiplier,int maxOccupancy,boolean active,LocalDate validFrom,LocalDate validTo) {
        public RatePlan { required(id,"id");required(name,"name");required(roomType,"roomType"); currency=Objects.requireNonNullElse(currency,"EUR").toUpperCase(Locale.ROOT);if(!currency.matches("[A-Z]{3}"))throw new IllegalArgumentException("Invalid currency");if(baseRate==null||baseRate.signum()<=0)throw new IllegalArgumentException("baseRate must be positive");weekendMultiplier=Objects.requireNonNullElse(weekendMultiplier,BigDecimal.ONE);highDemandMultiplier=Objects.requireNonNullElse(highDemandMultiplier,BigDecimal.ONE);new DynamicPricingEngine.Rules(baseRate,weekendMultiplier,highDemandMultiplier,currency,maxOccupancy);if(validFrom!=null&&validTo!=null&&validTo.isBefore(validFrom))throw new IllegalArgumentException("validTo must not precede validFrom"); }
    }
    public CommercialRepository(String url,String user,String password,int poolSize){super(url,user,password,poolSize);}
    public void saveRoom(Room r)throws SQLException {withConnection(c->{String sql="INSERT INTO hotel_rooms(room_id,room_type,room_number,floor_number,capacity,status,amenities) VALUES(?,?,?,?,?,?,?::jsonb) ON CONFLICT(room_id) DO UPDATE SET room_type=EXCLUDED.room_type,room_number=EXCLUDED.room_number,floor_number=EXCLUDED.floor_number,capacity=EXCLUDED.capacity,status=EXCLUDED.status,amenities=EXCLUDED.amenities,updated_at=NOW()";try(PreparedStatement p=c.prepareStatement(sql)){p.setString(1,r.id());p.setString(2,r.roomType());p.setString(3,r.roomNumber());p.setInt(4,r.floor());p.setInt(5,r.capacity());p.setString(6,r.status());p.setString(7,ApiJson.write(r.amenities()));p.executeUpdate();}return null;});}
    public List<Room> rooms(String type)throws SQLException{return withConnection(c->{String sql="SELECT * FROM hotel_rooms"+(type==null||type.isBlank()?"":" WHERE room_type=?")+" ORDER BY room_type,room_number";try(PreparedStatement p=c.prepareStatement(sql)){if(type!=null&&!type.isBlank())p.setString(1,type);try(ResultSet r=p.executeQuery()){List<Room> out=new ArrayList<>();while(r.next())out.add(new Room(r.getString("room_id"),r.getString("room_type"),r.getString("room_number"),r.getInt("floor_number"),r.getInt("capacity"),r.getString("status"),parseArray(r.getString("amenities"))));return out;}}});}
    public void saveRatePlan(RatePlan r)throws SQLException{withConnection(c->{String sql="INSERT INTO rate_plans(rate_plan_id,name,room_type,currency,base_rate,weekend_multiplier,high_demand_multiplier,max_occupancy,active,valid_from,valid_to) VALUES(?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(rate_plan_id) DO UPDATE SET name=EXCLUDED.name,room_type=EXCLUDED.room_type,currency=EXCLUDED.currency,base_rate=EXCLUDED.base_rate,weekend_multiplier=EXCLUDED.weekend_multiplier,high_demand_multiplier=EXCLUDED.high_demand_multiplier,max_occupancy=EXCLUDED.max_occupancy,active=EXCLUDED.active,valid_from=EXCLUDED.valid_from,valid_to=EXCLUDED.valid_to,updated_at=NOW()";try(PreparedStatement p=c.prepareStatement(sql)){p.setString(1,r.id());p.setString(2,r.name());p.setString(3,r.roomType());p.setString(4,r.currency());p.setBigDecimal(5,r.baseRate());p.setBigDecimal(6,r.weekendMultiplier());p.setBigDecimal(7,r.highDemandMultiplier());p.setInt(8,r.maxOccupancy());p.setBoolean(9,r.active());p.setObject(10,r.validFrom());p.setObject(11,r.validTo());p.executeUpdate();}return null;});}
    public List<RatePlan> ratePlans()throws SQLException{return withConnection(c->{try(PreparedStatement p=c.prepareStatement("SELECT * FROM rate_plans ORDER BY name,rate_plan_id");ResultSet r=p.executeQuery()){List<RatePlan> out=new ArrayList<>();while(r.next())out.add(new RatePlan(r.getString("rate_plan_id"),r.getString("name"),r.getString("room_type"),r.getString("currency"),r.getBigDecimal("base_rate"),r.getBigDecimal("weekend_multiplier"),r.getBigDecimal("high_demand_multiplier"),r.getInt("max_occupancy"),r.getBoolean("active"),r.getObject("valid_from",LocalDate.class),r.getObject("valid_to",LocalDate.class)));return out;}});}
    public Optional<RatePlan> ratePlan(String id,LocalDate from,LocalDate to)throws SQLException{return withConnection(c->{try(PreparedStatement p=c.prepareStatement("SELECT * FROM rate_plans WHERE rate_plan_id=? AND active=TRUE AND (valid_from IS NULL OR valid_from<=?) AND (valid_to IS NULL OR valid_to>=?)")){p.setString(1,id);p.setObject(2,from);p.setObject(3,to);try(ResultSet r=p.executeQuery()){return r.next()?Optional.of(new RatePlan(r.getString("rate_plan_id"),r.getString("name"),r.getString("room_type"),r.getString("currency"),r.getBigDecimal("base_rate"),r.getBigDecimal("weekend_multiplier"),r.getBigDecimal("high_demand_multiplier"),r.getInt("max_occupancy"),r.getBoolean("active"),r.getObject("valid_from",LocalDate.class),r.getObject("valid_to",LocalDate.class))):Optional.empty();}}});}
    public Map<String,Object> availability(String roomType,LocalDate from,LocalDate to,int guests)throws SQLException{return withConnection(c->{String sql="SELECT COUNT(*) FILTER (WHERE r.status='ACTIVE' AND r.capacity>=?) AS total_rooms, COUNT(*) FILTER (WHERE r.status='ACTIVE' AND r.capacity>=? AND NOT EXISTS (SELECT 1 FROM hotel_bookings b WHERE b.room_id=r.room_id AND b.deleted_at IS NULL AND b.status NOT IN ('CANCELLED','CHECKED_OUT') AND b.check_in < ? AND b.check_out > ?)) AS available_rooms FROM hotel_rooms r WHERE r.room_type=?";try(PreparedStatement p=c.prepareStatement(sql)){p.setInt(1,guests);p.setInt(2,guests);p.setObject(3,to);p.setObject(4,from);p.setString(5,roomType);try(ResultSet r=p.executeQuery()){r.next();int total=r.getInt("total_rooms"),available=r.getInt("available_rooms");return Map.of("roomType",roomType,"checkIn",from.toString(),"checkOut",to.toString(),"totalRooms",total,"availableRooms",available,"available",available>0,"occupancyRatio",total==0?BigDecimal.ZERO:BigDecimal.valueOf(total-available).divide(BigDecimal.valueOf(total),4,java.math.RoundingMode.HALF_UP));}}});}
    private static List<String> parseArray(String json){try{Object v=ApiJson.object("{\"v\":"+json+"}").get("v");if(v instanceof List<?> l)return l.stream().map(String::valueOf).toList();}catch(Exception ignored){}return List.of();}
    private static void required(String s,String n){if(s==null||s.isBlank())throw new IllegalArgumentException(n+" is required");}
}
